export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be a real date in YYYY-MM-DD format.',
  DISCOUNT_INVALID: 'Discount must be a number between 0 and 100.',
  INVOICE_INVALID: 'Invoice must have a lines array.',
  LINE_INVALID: 'Line must have qty and unitPrice.',
  LINE_NOT_FOUND: 'No line with that SKU on the invoice.',
  NO_LINES: 'Invoice must have at least one line item.',
  NOT_DRAFT: 'Invoice must have draft status to be modified.',
  NOT_ISSUED: 'Invoice must be issued or partially paid to record a payment.',
  OVERPAYMENT: 'Payment exceeds the balance due on the invoice.',
  QTY_INVALID: 'Item quantity must be a positive integer.',
  TERMS_INVALID: 'Payment terms must be NET14, NET30, or EOM.',
  UNKNOWN_CURRENCY: 'Currency not recognized. Supported currencies: EUR, USD, GBP.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
  VOUCHER_EXISTS: 'Only one voucher per invoice.',
  CREDIT_TOO_HIGH: 'Credit note amount cannot exceed the invoice total.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

