test('getCustomer finds customer by mixed case and whitespace id', () => {
  const r = getCustomer(' c-007 ');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Halvorsen Architects');
});

test('getCustomer still reports unknown id for non-existent normalized ids', () => {
  assert.deepEqual(getCustomer('c-999'), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
  assert.deepEqual(getCustomer(' C-999 '), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

// mergeCustomers tests
test('mergeCustomers merges one customer into another', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
    { customerId: 'C-002', number: 'INV-002', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 1);
  assert.equal(r.value.customers[0].id, 'C-002');
  assert.equal(r.value.invoices.length, 2);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
  assert.equal(r.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers removes customer from customers list', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
    { id: 'C-003', name: 'Customer C', email: 'c@example.com', country: 'NL', tier: 'silver' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 2);
  assert.equal(r.value.customers.some((c) => c.id === 'C-001'), false);
  assert.equal(r.value.customers.some((c) => c.id === 'C-002'), true);
  assert.equal(r.value.customers.some((c) => c.id === 'C-003'), true);
});

test('mergeCustomers reassigns all invoices from fromId to intoId', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
    { customerId: 'C-001', number: 'INV-002', status: 'issued' },
    { customerId: 'C-001', number: 'INV-003', status: 'issued' },
    { customerId: 'C-002', number: 'INV-004', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 4);
  assert.equal(r.value.invoices.filter((inv) => inv.customerId === 'C-001').length, 0);
  assert.equal(r.value.invoices.filter((inv) => inv.customerId === 'C-002').length, 4);
});

test('mergeCustomers reports SAME_CUSTOMER when merging into same customer', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-001');
  assert.deepEqual(r, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers reports CUSTOMER_NOT_FOUND for unknown fromId', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-999', 'C-002');
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers reports CUSTOMER_NOT_FOUND for unknown intoId', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-999');
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers does not mutate original customers array', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];
  const customersCopy = JSON.parse(JSON.stringify(customers));

  mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.deepEqual(customers, customersCopy);
});

test('mergeCustomers does not mutate original invoices array', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
  ];
  const invoicesCopy = JSON.parse(JSON.stringify(invoices));

  mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.deepEqual(invoices, invoicesCopy);
});

test('mergeCustomers with normalized IDs (lowercase)', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, 'c-001', 'c-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 1);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers with normalized IDs (whitespace)', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    { customerId: 'C-001', number: 'INV-001', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, ' C-001 ', ' C-002 ');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers with same normalized IDs reports SAME_CUSTOMER', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, ' c-001 ', 'C-001');
  assert.deepEqual(r, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers with no invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.customers.length, 1);
  assert.equal(r.value.invoices.length, 0);
});

test('mergeCustomers preserves intoId customer data', () => {
  const customers = [
