});

test('mergeCustomers preserves other invoice data', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [
    {
      customerId: 'C-001',
      number: 'INV-001',
      status: 'issued',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      lines: [{ sku: 'DES-HOUR', qty: 2 }],
    },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  const inv = r.value.invoices[0];
  assert.equal(inv.customerId, 'C-002');
  assert.equal(inv.number, 'INV-001');
  assert.equal(inv.status, 'issued');
  assert.equal(inv.issueDate, '2026-10-07');
  assert.equal(inv.dueDate, '2026-11-06');
  assert.equal(inv.lines.length, 1);
});

test('mergeCustomers with mix of invoices from both customers', () => {
