    { customerId: 'C-003', number: 'INV-004', status: 'issued' },
    { customerId: 'C-002', number: 'INV-005', status: 'issued' },
    { customerId: 'C-001', number: 'INV-006', status: 'issued' },
  ];

  const r = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 6);
  assert.equal(r.value.invoices.filter((inv) => inv.customerId === 'C-002').length, 5);
  assert.equal(r.value.invoices.filter((inv) => inv.customerId === 'C-003').length, 1);
});

test('mergeCustomers returns proper structure', () => {
  const customers = [
    { id: 'C-001', name: 'Customer A', email: 'a@example.com', country: 'NL', tier: 'gold' },
    { id: 'C-002', name: 'Customer B', email: 'b@example.com', country: 'NL', tier: 'standard' },
